mapper.select:
SELECT r.RECRUITMENT_NO, r.MAX_PARTICIPANTS, r.RECRUITMENT_STATUS, p.P_CREATE_DATE AS P_CREATE_DATE, r.REC_END_DATE, r.REGION, r.PRODUCT_URL, q.QR_ID, p.PRODUCT_NO, p.PRODUCT_TITLE AS PRODUCT_NAME, p.PRODUCT_PRICE, p.PRODUCT_COUNT, p.READ_COUNT, p.CATEGORY_NO,
m.MEMBER_NO AS hostNo, m.MEMBER_NICK AS hostName, m.MEMBER_GRADE AS hostGrade,
(SELECT I.IMG_PATH || I.IMG_RENAME FROM IMG I WHERE I.IMG_TYPE_NO = r.RECRUITMENT_NO AND I.IMG_LEVEL = 0 AND I.IMG_TYPE = 'RECRUITMENT' FETCH FIRST 1 ROWS ONLY) AS thumbnail
FROM RECRUITMENT_ROOM r JOIN PRODUCT p ON r.PRODUCT_NO = p.PRODUCT_NO JOIN MEMBER m ON r.MEMBER_NO = m.MEMBER_NO LEFT JOIN QR_AUTH q ON r.RECRUITMENT_NO = q.RECRUITMENT_NO LEFT JOIN CATEGORY c ON p.CATEGORY_NO = c.CATEGORY_NO
WHERE r.RECRUITMENT_STATUS != '완료' AND p.PRODUCT_PRICE BETWEEN ${minValue} AND ${maxValue}
AND p.CATEGORY_NO IN (${categoryNo})
AND p.PRODUCT_TITLE LIKE #{searchValue}
AND c.PARENT_CATEGORY_NO = ${categoryNoParents}
